export const storageKey='mengyuan-single-flow-demo-v2';
export const clone=x=>JSON.parse(JSON.stringify(x));
export const steps={script:'剧本协作',storyboard:'分镜生成',review:'分镜质检',dialogue:'台词生成',image:'参考图生成',shotPrompt:'镜头提示词',style:'风格推荐',template:'模板建立',video:'视频生成',voice:'配音',music:'配乐',subtitle:'字幕'};
export const defaults={script:'根据创意 {{idea}}、对话要求 {{instruction}} 输出完整剧本。',storyboard:'将定稿 {{script}} 拆为分镜 JSON，包含稳定镜头 ID、台词、角色/场景/道具、提示词和时长。',review:'对照剧本 {{script}} 与分镜 {{shots}}，检查信息遗漏、情绪错位和动作逻辑。返回 issues 和完整 proposedShots，保留镜头 ID。',dialogue:'按剧本 {{script}} 为镜头 {{shot}} 生成自然台词。',image:'按素材描述 {{asset}} 和风格 {{style}} 生成一致的参考图。',shotPrompt:'按镜头 {{shot}}、剧本 {{script}} 和风格 {{style}} 编写视频提示词。',style:'根据剧本 {{script}} 推荐视觉风格。',template:'把风格要求 {{style}} 整理为可复用模板。',video:'根据镜头 {{shot}} 和参考图 {{assets}} 生成视频。',voice:'按台词 {{dialogue}} 和音色 {{voice}} 生成配音。',music:'按剧本 {{script}} 与时长 {{duration}} 生成配乐。',subtitle:'根据台词 {{dialogue}} 和时长 {{duration}} 生成字幕。'};
export function initial(){return {version:2,idea:'雨夜里，一名快递员发现收件人是十年前帮助过自己的老师，决定亲手送出这份迟到的感谢。',title:'雨夜送达',instruction:'',scripts:[],candidates:[],final:null,shots:[],boardVersion:0,boardScriptId:null,boardConfirmed:0,report:null,history:[],prompts:{},defaults:{...defaults},models:{},configVersion:1,styleVersion:1,styles:[{name:'现代电影',text:'写实人物，雨夜冷色环境，室内暖光；自然光影，克制表演。'},{name:'古风写意',text:'古代服饰与建筑，水墨质感，柔和侧光，避免现代物件。'}],styleIndex:0,finishing:{voice:'温暖叙述',music:'轻钢琴',subtitles:true},jobs:[]};}
export function read(){try{const x=JSON.parse(localStorage.getItem(storageKey));return x?.version===2?x:initial()}catch{return initial()}}
export function write(s){localStorage.setItem(storageKey,JSON.stringify(s));}
export function taskSnapshot(s,step){return {step,configVersion:s.configVersion,model:clone(s.models[step]||{name:'演示模型'}),prompt:s.prompts[step]||s.defaults[step],scriptId:s.final?.id||null,boardVersion:s.boardVersion,styleVersion:s.styleVersion};}
export function selectFinal(s,candidate){if(!candidate?.text?.trim())throw Error('剧本不能为空');if(s.final?.id===candidate.id)return;s.final=clone(candidate);s.report=null;s.boardConfirmed=0;}
export function boardStale(s){return !!s.shots.length&&s.boardScriptId!==s.final?.id;}
export function changed(s){s.boardVersion++;s.boardConfirmed=0;}
export function makeShots(s){if(!s.final)throw Error('请先在备选区选定剧本');const courier=s.final.text.includes('包裹')&&s.final.text.includes('取出');const parts=s.final.text.split('\n').filter(x=>x.trim());return [0,1,2].map((i)=>({id:`shot-${i+1}`,dialogue:!courier?'我们开始吧。':i===0?'这门牌，怎么这么熟悉？':i===1?'老师，您的包裹。':'谢谢您，我一直记得。',speaker:!courier?'主角':i===2?'老师':'快递员',emotion:i===2?'温暖':'克制',duration:20,prompt:courier&&i===1?'快递员站在门口，将包裹递给老师。':(parts[i+1]||parts[i]||s.final.text),assets:[{kind:'角色',name:!courier?'主角':i===2?'老师':'快递员',description:'人物外观与服饰保持一致',image:null,confirmed:false},{kind:'场景',name:!courier?'故事场景':i===0?'雨夜街道':'老师家门口',description:'雨夜冷光与室内暖光',image:null,confirmed:false},{kind:'道具',name:courier?'包裹':'关键道具',description:'被雨衣护住的纸盒包裹',image:null,confirmed:false}],video:null,videoStale:false}));}
export function validateReport(report,s){if(!report||report.schemaVersion!==1||report.baseBoardVersion!==s.boardVersion||report.scriptId!==s.final?.id||boardStale(s))throw Error('报告已过期，请对当前定稿和分镜重新质检');if(!Array.isArray(report.issues)||!Array.isArray(report.proposedShots)||report.proposedShots.length!==s.shots.length)throw Error('报告结构无效：镜头数量不匹配');if(report.issues.some(issue=>!issue||!s.shots.some(sh=>sh.id===issue.shotId)))throw Error('报告结构无效：问题引用未知镜头');const ids=new Set();for(const r of report.proposedShots){if(!r.id||ids.has(r.id)||!s.shots.some(x=>x.id===r.id)||typeof r.prompt!=='string'||!r.prompt.trim()||typeof r.dialogue!=='string')throw Error('报告结构无效：镜头 ID 或文本字段错误');ids.add(r.id);}return true;}
export function applyReport(s){validateReport(s.report,s);if(!s.report.issues.length)throw Error('当前报告没有需要替换的建议');s.history.push({boardVersion:s.boardVersion,scriptId:s.boardScriptId,shots:clone(s.shots)});for(const proposal of s.report.proposedShots){const shot=s.shots.find(x=>x.id===proposal.id);if(shot.prompt!==proposal.prompt||shot.dialogue!==proposal.dialogue){shot.videoStale=!!shot.video;shot.assets.forEach(a=>a.confirmed=false);shot.prompt=proposal.prompt;shot.dialogue=proposal.dialogue;}}changed(s);}
